prompt:
[aang:workflow] Run this workflow with the Workflow tool, passing the script verbatim, and reply with one sentence:
export const meta = { name: 'aang-echo', description: 'Echo words through workflow agents', phases: [{ title: 'Echo' }, { title: 'Report' }] }
const words = await parallel([
  () => agent('[aang:wf-left] Run `echo left` with the Bash tool and report its output.', { label: 'left', phase: 'Echo' }),
  () => agent('[aang:wf-right] Run `echo right` with the Bash tool and report its output.', { label: 'right', phase: 'Echo' }),
])
const report = await agent('[aang:wf-report] Run `echo report` with the Bash tool and report its output.', { label: 'report', phase: 'Report' })
return { words, report }
